from datetime import datetime, timedelta

def _parse_field(field: str, min_v: int, max_v: int) -> set:
    """Tolkar ett cron-fält (stöd för '*' och kommaseparerade heltal)."""
    if field == '*':
        return set(range(min_v, max_v + 1))
    return {int(p) for p in field.split(',')}

def next_run(cron_expr: str) -> datetime:
    """
    Räknar ut nästa körningstid för ett cron-uttryck
    'minute hour day month weekday' (weekday: 0=söndag ... 6=lördag).
    Notera: standard-cron saknar årsfält, så nästa förekomst hittas
    oavsett år (t.ex. '7 oktober' matchar första kommande 7 oktober).
    """
    minute_f, hour_f, day_f, month_f, weekday_f = cron_expr.split()

    minutes = sorted(_parse_field(minute_f, 0, 59))
    hours = sorted(_parse_field(hour_f, 0, 23))
    days = _parse_field(day_f, 1, 31) if day_f != '*' else None
    months = _parse_field(month_f, 1, 12)
    weekdays = _parse_field(weekday_f, 0, 6) if weekday_f != '*' else None

    now = datetime.now().replace(second=0, microsecond=0)
    d = now.date()

    def date_matches(dt) -> bool:
        if dt.month not in months:
            return False
        if days is not None and dt.day not in days:
            return False
        if weekdays is not None:
            # Python: Monday=0 ... Sunday=6 -> konvertera till cron (Sunday=0)
            cron_wd = (dt.weekday() + 1) % 7
            if cron_wd not in weekdays:
                return False
        return True

    # Sök upp till 10 år framåt (mer än nog för normala cron-uttryck)
    for _ in range(366 * 10):
        if date_matches(d):
            for h in hours:
                for m in minutes:
                    candidate = datetime(d.year, d.month, d.day, h, m)
                    if candidate > now:
                        return candidate
        d += timedelta(days=1)

    raise ValueError("Ingen matchande körningstid hittades inom sökintervallet.")


if __name__ == "__main__":
    expr = '0 2 7 10 *'  # kl 02:00, 7 oktober, valfri veckodag
    print(f"Cron: '{expr}' -> Nästa körning: {next_run(expr)}")
```

