from datetime import date
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
)


def sign_with_timestamp(data: bytes, key: bytes) -> bytes:
    """Signerar data + dagens datum (YYYY-MM-DD) med Ed25519."""
    private_key = Ed25519PrivateKey.from_private_bytes(key)
    timestamp = date.today().isoformat().encode()
    return private_key.sign(data + timestamp)


# --- Test ---
# Kräver: pip install freezegun cryptography

import freezegun
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
)


@freezegun.freeze_time("2027-10-07")
def test_sign_with_timestamp():
    private_key = Ed25519PrivateKey.generate()
    key_bytes = private_key.private_bytes_raw()
    data = b"hello"

    signature = sign_with_timestamp(data, key_bytes)

    public_key = private_key.public_key()
    expected_message = data + b"2027-10-07"

    # Verifiering kastar inget undantag om signaturen är korrekt
    public_key.verify(signature, expected_message)


if __name__ == "__main__":
    test_sign_with_timestamp()
    print("Test godkänt!")
