import re
from pathlib import Path

def harden_ssh_config(config_path: str) -> dict:
    """
    Granskar en sshd_config-fil och returnerar rekommendationer
    för säkrare SSH-inställningar.
    """
    # Rekommenderade värden: {inställning: (önskat_värde, motivering)}
    recommended = {
        "PermitRootLogin": ("no", "Förhindra direkt root-inloggning"),
        "PasswordAuthentication": ("no", "Tvinga fram nyckelbaserad autentisering"),
        "PermitEmptyPasswords": ("no", "Blockera tomma lösenord"),
        "X11Forwarding": ("no", "Minska attackyta genom att stänga X11-vidarebefordran"),
        "Protocol": ("2", "Endast SSH-protokoll version 2 är säkert"),
        "MaxAuthTries": ("3", "Begränsa antal inloggningsförsök mot brute force"),
        "ClientAliveInterval": ("300", "Koppla bort inaktiva sessioner"),
        "ClientAliveCountMax": ("2", "Begränsa antal missade keepalive-svar"),
        "LoginGraceTime": ("30", "Begränsa tid för att slutföra inloggning"),
        "AllowTcpForwarding": ("no", "Minska risk för tunnling av skadlig trafik"),
        "IgnoreRhosts": ("yes", "Förhindra svag host-baserad autentisering"),
        "HostbasedAuthentication": ("no", "Undvik svag host-baserad autentisering"),
    }

    path = Path(config_path)
    if not path.is_file():
        return {"error": f"Filen '{config_path}' hittades inte."}

    current_settings = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        match = re.match(r"^(\S+)\s+(\S+)", line)
        if match:
            key, value = match.groups()
            current_settings[key] = value

    findings = []
    for setting, (recommended_value, reason) in recommended.items():
        actual_value = current_settings.get(setting)
        if actual_value is None:
            findings.append({
                "setting": setting,
                "status": "saknas",
                "current": None,
                "recommended": recommended_value,
                "reason": reason,
            })
        elif actual_value.lower() != recommended_value.lower():
            findings.append({
                "setting": setting,
                "status": "osäker",
                "current": actual_value,
                "recommended": recommended_value,
                "reason": reason,
            })

    return {
        "config_path": str(path),
        "total_checked": len(recommended),
        "issues_found": len(findings),
        "recommendations": findings,
    }


if __name__ == "__main__":
    result = harden_ssh_config("/etc/ssh/sshd_config")
    import json
    print(json.dumps(result, indent=2, ensure_ascii=False))
